
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_x1b95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_x1b95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.082822976513258e+00, -3.025204084830917e+00, -2.944510010961120e+00, -2.832820206520233e+00, -2.680819202795221e+00, -2.478911161180305e+00, -2.219831582968448e+00, -1.903278549441840e+00, -1.541834171922903e+00, -1.162846355317893e+00, -7.941007863868198e-01, -5.520010028142736e-01, -4.603366172498595e-01, -3.768027984856291e-01, -2.749227282336958e-01, -1.776175286475501e-01, -1.055218693287060e-01, -5.526159244433988e-02, -3.271425492074788e-02, -2.234119649207282e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


